from sqlalchemy.orm import Session
from sqlalchemy import func
from typing import Optional
from datetime import date, datetime, timedelta

from ..models.admin import AdminUser, VerificationRequest
from ..models.user import User, UserRole, Role
from ..models.doctor import DoctorProfile
from ..models.hospital import Hospital
from ..models.pharmacy import Pharmacy
from ..models.appointment import Appointment
from ..models.emergency import EmergencyRequest
from ..models.search import AuditLog, SecurityLog
from ..models.review import Feedback
from ..schemas.admin import (
    VerificationRequestResponse, VerificationActionRequest,
    AdminDashboardResponse, AuditLogResponse,
    FeedbackResponse, FeedbackResolveRequest,
)
from ..core.exceptions import NotFoundException, BadRequestException, ForbiddenException
from ..utils.helpers import build_pagination_meta


class AdminService:
    def __init__(self, db: Session):
        self.db = db

    def get_dashboard(self) -> AdminDashboardResponse:
        total_users = self.db.query(User).count()
        total_doctors = self.db.query(DoctorProfile).count()
        total_hospitals = self.db.query(Hospital).count()
        total_pharmacies = self.db.query(Pharmacy).count()
        total_appointments = self.db.query(Appointment).count()
        pending_verifs = self.db.query(VerificationRequest).filter(
            VerificationRequest.status == "pending"
        ).count()
        active_emergencies = self.db.query(EmergencyRequest).filter(
            EmergencyRequest.status.in_(["pending", "dispatched", "en-route"])
        ).count()
        recent_signups = self.db.query(User).filter(
            User.created_at >= datetime.utcnow() - timedelta(days=7)
        ).count()

        return AdminDashboardResponse(
            total_users=total_users,
            total_doctors=total_doctors,
            total_hospitals=total_hospitals,
            total_pharmacies=total_pharmacies,
            total_appointments=total_appointments,
            pending_verifications=pending_verifs,
            active_emergencies=active_emergencies,
            recent_signups=recent_signups,
        )

    def get_verifications(self, status: Optional[str] = None, page: int = 1, size: int = 20) -> dict:
        query = self.db.query(VerificationRequest)
        if status:
            query = query.filter(VerificationRequest.status == status)
        query = query.order_by(VerificationRequest.created_at.desc())
        total = query.count()
        items = query.offset((page - 1) * size).limit(size).all()
        return {
            "items": [VerificationRequestResponse.model_validate(v) for v in items],
            **build_pagination_meta(total, page, size),
        }

    def process_verification(self, verification_id: str, admin_user_id: str, data: VerificationActionRequest) -> VerificationRequestResponse:
        vreq = self.db.query(VerificationRequest).filter(VerificationRequest.id == verification_id).first()
        if not vreq:
            raise NotFoundException("Verification request not found")

        valid_statuses = ["approved", "rejected", "more-info"]
        if data.status not in valid_statuses:
            raise BadRequestException(f"Invalid status. Must be one of: {valid_statuses}")

        vreq.status = data.status
        vreq.reviewed_by = admin_user_id
        if data.rejection_reason:
            vreq.rejection_reason = data.rejection_reason
        if data.notes:
            vreq.notes = data.notes

        # Update the entity's verification status
        if data.status == "approved":
            if vreq.entity_type == "doctor":
                profile = self.db.query(DoctorProfile).filter(DoctorProfile.id == vreq.entity_id).first()
                if profile:
                    profile.is_verified = True
            elif vreq.entity_type == "hospital":
                hospital = self.db.query(Hospital).filter(Hospital.id == vreq.entity_id).first()
                if hospital:
                    hospital.is_verified = True
            elif vreq.entity_type == "pharmacy":
                pharmacy = self.db.query(Pharmacy).filter(Pharmacy.id == vreq.entity_id).first()
                if pharmacy:
                    pharmacy.is_verified = True

        self.db.commit()
        self.db.refresh(vreq)
        return VerificationRequestResponse.model_validate(vreq)

    def get_audit_logs(self, page: int = 1, size: int = 20, user_id: Optional[str] = None, action: Optional[str] = None) -> dict:
        query = self.db.query(AuditLog)
        if user_id:
            query = query.filter(AuditLog.user_id == user_id)
        if action:
            query = query.filter(AuditLog.action.ilike(f"%{action}%"))
        query = query.order_by(AuditLog.created_at.desc())
        total = query.count()
        logs = query.offset((page - 1) * size).limit(size).all()
        return {
            "items": [AuditLogResponse.model_validate(l) for l in logs],
            **build_pagination_meta(total, page, size),
        }

    def get_feedback(self, status: Optional[str] = None, page: int = 1, size: int = 20) -> dict:
        query = self.db.query(Feedback)
        if status:
            query = query.filter(Feedback.status == status)
        query = query.order_by(Feedback.created_at.desc())
        total = query.count()
        items = query.offset((page - 1) * size).limit(size).all()
        return {
            "items": [FeedbackResponse.model_validate(f) for f in items],
            **build_pagination_meta(total, page, size),
        }

    def resolve_feedback(self, feedback_id: str, admin_user_id: str, data: FeedbackResolveRequest) -> FeedbackResponse:
        fb = self.db.query(Feedback).filter(Feedback.id == feedback_id).first()
        if not fb:
            raise NotFoundException("Feedback not found")
        fb.status = data.status
        fb.response = data.response
        fb.resolved_by = admin_user_id
        self.db.commit()
        self.db.refresh(fb)
        return FeedbackResponse.model_validate(fb)

    def toggle_user_active(self, user_id: str, is_active: bool) -> dict:
        user = self.db.query(User).filter(User.id == user_id).first()
        if not user:
            raise NotFoundException("User not found")
        user.is_active = is_active
        self.db.commit()
        return {"user_id": user_id, "is_active": is_active}

    def get_system_stats(self) -> dict:
        from ..models.blood_donation import BloodDonor, BloodRequest
        from ..models.oxygen import OxygenRequest as OxyReq
        return {
            "users": self.db.query(User).count(),
            "doctors": self.db.query(DoctorProfile).count(),
            "hospitals": self.db.query(Hospital).count(),
            "pharmacies": self.db.query(Pharmacy).count(),
            "appointments": self.db.query(Appointment).count(),
            "blood_donors": self.db.query(BloodDonor).count(),
            "blood_requests": self.db.query(BloodRequest).count(),
            "oxygen_requests": self.db.query(OxyReq).count(),
            "emergencies": self.db.query(EmergencyRequest).count(),
        }

// src/services/adminService.ts

import {
  Admin, SystemStats, User, DoctorVerification,
  HospitalVerification, PharmacyVerification,
  SystemAnalytics, BloodStockAnalytics,
  Report, Feedback, EmergencyAlert,
  SecurityLog, AdminDashboardData,
  SystemHealth
} from '../types/admin';

const API_BASE_URL = import.meta.env.VITE_API_URL || 'http://localhost:5000/api/admin';

class AdminService {
  private token: string = '';

  setToken(token: string) {
    this.token = token;
  }

  private getHeaders() {
    return {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${this.token}`
    };
  }

  // Authentication
  async login(username: string, password: string): Promise<{ token: string; admin: Admin }> {
    const response = await fetch(`${API_BASE_URL}/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    });
    return response.json();
  }

  async logout(): Promise<void> {
    await fetch(`${API_BASE_URL}/logout`, {
      method: 'POST',
      headers: this.getHeaders()
    });
  }

  // Dashboard
  async getDashboardData(): Promise<AdminDashboardData> {
    const response = await fetch(`${API_BASE_URL}/dashboard`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  // User Management
  async getUsers(filters?: any): Promise<User[]> {
    const params = new URLSearchParams(filters).toString();
    const response = await fetch(`${API_BASE_URL}/users?${params}`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async getUserDetails(userId: string): Promise<User> {
    const response = await fetch(`${API_BASE_URL}/users/${userId}`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async updateUser(userId: string, data: Partial<User>): Promise<void> {
    await fetch(`${API_BASE_URL}/users/${userId}`, {
      method: 'PUT',
      headers: this.getHeaders(),
      body: JSON.stringify(data)
    });
  }

  async blockUser(userId: string, reason: string): Promise<void> {
    await fetch(`${API_BASE_URL}/users/${userId}/block`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify({ reason })
    });
  }

  async deleteUser(userId: string): Promise<void> {
    await fetch(`${API_BASE_URL}/users/${userId}`, {
      method: 'DELETE',
      headers: this.getHeaders()
    });
  }

  async unblockUser(userId: string): Promise<void> {
    await fetch(`${API_BASE_URL}/users/${userId}/unblock`, {
      method: 'POST',
      headers: this.getHeaders()
    });
  }

  // Doctor Verification
  async getPendingDoctorVerifications(): Promise<DoctorVerification[]> {
    const response = await fetch(`${API_BASE_URL}/verifications/doctors/pending`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async verifyDoctor(verificationId: string, status: string, notes?: string): Promise<void> {
    await fetch(`${API_BASE_URL}/verifications/doctors/${verificationId}`, {
      method: 'PUT',
      headers: this.getHeaders(),
      body: JSON.stringify({ status, notes })
    });
  }

  // Hospital Verification
  async getPendingHospitalVerifications(): Promise<HospitalVerification[]> {
    const response = await fetch(`${API_BASE_URL}/verifications/hospitals/pending`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async verifyHospital(verificationId: string, status: string): Promise<void> {
    await fetch(`${API_BASE_URL}/verifications/hospitals/${verificationId}`, {
      method: 'PUT',
      headers: this.getHeaders(),
      body: JSON.stringify({ status })
    });
  }

  // Pharmacy Verification
  async getPendingPharmacyVerifications(): Promise<PharmacyVerification[]> {
    const response = await fetch(`${API_BASE_URL}/verifications/pharmacies/pending`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async verifyPharmacy(verificationId: string, status: string): Promise<void> {
    await fetch(`${API_BASE_URL}/verifications/pharmacies/${verificationId}`, {
      method: 'PUT',
      headers: this.getHeaders(),
      body: JSON.stringify({ status })
    });
  }

  // Analytics
  async getSystemAnalytics(period: string): Promise<SystemAnalytics> {
    const response = await fetch(`${API_BASE_URL}/analytics?period=${period}`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async getSystemStats(): Promise<SystemStats> {
    const response = await fetch(`${API_BASE_URL}/stats`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  // Blood Stock Analytics
  async getBloodStockAnalytics(): Promise<BloodStockAnalytics> {
    const response = await fetch(`${API_BASE_URL}/blood-analytics`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  // Reports
  async generateReport(data: Partial<Report>): Promise<Report> {
    const response = await fetch(`${API_BASE_URL}/reports/generate`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify(data)
    });
    return response.json();
  }

  async getReports(): Promise<Report[]> {
    const response = await fetch(`${API_BASE_URL}/reports`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async downloadReport(reportId: string): Promise<Blob> {
    const response = await fetch(`${API_BASE_URL}/reports/${reportId}/download`, {
      headers: this.getHeaders()
    });
    return response.blob();
  }

  // Feedback Management
  async getFeedbacks(filters?: any): Promise<Feedback[]> {
    const params = new URLSearchParams(filters).toString();
    const response = await fetch(`${API_BASE_URL}/feedbacks?${params}`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async respondToFeedback(feedbackId: string, response: string): Promise<void> {
    await fetch(`${API_BASE_URL}/feedbacks/${feedbackId}/respond`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify({ response })
    });
  }

  async updateFeedbackStatus(feedbackId: string, status: string): Promise<void> {
    await fetch(`${API_BASE_URL}/feedbacks/${feedbackId}/status`, {
      method: 'PUT',
      headers: this.getHeaders(),
      body: JSON.stringify({ status })
    });
  }

  // Emergency Monitoring
  async getActiveEmergencies(): Promise<EmergencyAlert[]> {
    const response = await fetch(`${API_BASE_URL}/emergencies/active`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async updateEmergencyStatus(emergencyId: string, status: string): Promise<void> {
    await fetch(`${API_BASE_URL}/emergencies/${emergencyId}/status`, {
      method: 'PUT',
      headers: this.getHeaders(),
      body: JSON.stringify({ status })
    });
  }

  async dispatchResponder(emergencyId: string, responderData: any): Promise<void> {
    await fetch(`${API_BASE_URL}/emergencies/${emergencyId}/dispatch`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify(responderData)
    });
  }

  // Security
  async getSecurityLogs(): Promise<SecurityLog[]> {
    const response = await fetch(`${API_BASE_URL}/security/logs`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async getSystemHealth(): Promise<SystemHealth> {
    const response = await fetch(`${API_BASE_URL}/security/health`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  // Notifications
  async sendSystemNotification(data: any): Promise<void> {
    await fetch(`${API_BASE_URL}/notifications/send`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify(data)
    });
  }

  async sendSMS(phone: string, message: string): Promise<void> {
    await fetch(`${API_BASE_URL}/notifications/sms`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify({ phone, message })
    });
  }

  async sendEmail(email: string, subject: string, message: string): Promise<void> {
    await fetch(`${API_BASE_URL}/notifications/email`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify({ email, subject, message })
    });
  }
}

export const adminService = new AdminService();

