const fetchUsers = async () => {
  setIsLoading(true);
  try {
    const token = localStorage.getItem('token');
    const params = new URLSearchParams();
    if (searchTerm) params.append('search', searchTerm);
    if (roleFilter !== 'all') params.append('role', roleFilter);
    if (statusFilter !== 'all') params.append('status', statusFilter);
    params.append('page', '1');
    params.append('size', '100');

    const res = await fetch(
      `${import.meta.env.VITE_API_URL || 'http://localhost:5000/api/v1'}/admin/users?${params.toString()}`,
      {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      }
    );
    const data = await res.json();
    if (data.success && data.data?.items) {
      const mapped: User[] = data.data.items.map((u: any) => ({
        id: u.id,
        firstName: u.full_name?.split(' ')[0] || '',
        lastName: u.full_name?.split(' ').slice(1).join(' ') || '',
        email: u.email,
        phone: u.phone || '',
        role: u.role || 'client',
        status: u.status || 'active',
        isVerified: u.is_verified || false,
        registeredDate: u.created_at ? new Date(u.created_at).toLocaleDateString() : '',
        lastActive: u.last_login_at || u.created_at || new Date().toISOString(),
      }));
      setUsers(mapped);
    } else {
      setUsers([]);
    }
  } catch (err) {
    console.error('Failed to fetch users:', err);
    setUsers([]);
  } finally {
    setIsLoading(false);
  }
};

